<?php require_once 'layout.php'; require_admin(); $db=db(); function upload_image(){ if(empty($_FILES['image']['name'])) return $_POST['old_image']??''; $ext=strtolower(pathinfo($_FILES['image']['name'],PATHINFO_EXTENSION)); if(!in_array($ext,['jpg','jpeg','png','gif','webp','svg'])) return $_POST['old_image']??''; $name='uploads/food_'.time().'_'.rand(100,999).'.'.$ext; move_uploaded_file($_FILES['image']['tmp_name'],__DIR__.'/'.$name); return $name; } if($_SERVER['REQUEST_METHOD']==='POST'){ $act=$_POST['act']; if($act==='save'){ $id=(int)($_POST['id']??0); $name=trim($_POST['name']); $price=(float)$_POST['price']; $cat=trim($_POST['category']); $img=upload_image(); if($id){$s=$db->prepare('UPDATE menu_items SET name=?,price=?,category=?,image=? WHERE id=?');$s->bind_param('sdssi',$name,$price,$cat,$img,$id);} else {$s=$db->prepare('INSERT INTO menu_items(name,price,category,image) VALUES(?,?,?,?)');$s->bind_param('sdss',$name,$price,$cat,$img);} $s->execute(); flash('Food item saved.'); } if($act==='delete'){ $id=(int)$_POST['id']; $s=$db->prepare('DELETE FROM menu_items WHERE id=?'); $s->bind_param('i',$id); $s->execute(); flash('Food item deleted.'); } redirect('admin_food_items.php'); } $edit=null; if(isset($_GET['edit'])){$id=(int)$_GET['edit'];$edit=$db->query("SELECT * FROM menu_items WHERE id=$id")->fetch_assoc();} $items=$db->query('SELECT * FROM menu_items ORDER BY id DESC'); page_header('Food Items',true); ?><h1>Food Items</h1><div class="admin-grid"><form class="panel" method="post" enctype="multipart/form-data"><h2><?= $edit?'Edit':'Add New' ?> Item</h2><input type="hidden" name="act" value="save"><input type="hidden" name="id" value="<?=$edit['id']??0?>"><input type="hidden" name="old_image" value="<?=h($edit['image']??'')?>"><label>Name<input name="name" required value="<?=h($edit['name']??'')?>"></label><label>Price<input type="number" name="price" min="1" step="0.01" required value="<?=h($edit['price']??'')?>"></label><label>Category<input name="category" required value="<?=h($edit['category']??'')?>"></label><label>Food Image<input type="file" name="image" accept="image/*"></label><button>Save Item</button></form><div class="cart-box"><table><tr><th>Image</th><th>Name</th><th>Price</th><th>Category</th><th>Actions</th></tr><?php while($i=$items->fetch_assoc()):?><tr><td><img class="mini" src="<?=h($i['image'])?>"></td><td><?=h($i['name'])?></td><td>₹<?=number_format($i['price'],0)?></td><td><?=h($i['category'])?></td><td><a class="button small" href="?edit=<?=$i['id']?>">Edit</a><form method="post" class="inline"><input type="hidden" name="act" value="delete"><input type="hidden" name="id" value="<?=$i['id']?>"><button class="danger" onclick="return confirm('Delete this item?')">Delete</button></form></td></tr><?php endwhile;?></table></div></div><?php page_footer(); ?>
